import{_ as l,o as i,c as e,a2 as t}from"./chunks/framework.DnrXFDHb.js";const c=JSON.parse('{"title":"算电岛技术深度拆解：100%绿电直连的算电岛，是真实用还是秀肌肉？","description":"","frontmatter":{"tags":["技术拆解","特锐德","算电岛","SST","碳化硅"],"updated":"2026-06-24T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"算电协同/_深化_2026-06-24_算电岛技术拆解.md","filePath":"算电协同/_深化_2026-06-24_算电岛技术拆解.md","lastUpdated":null}'),r={name:"算电协同/_深化_2026-06-24_算电岛技术拆解.md"};function o(n,a,h,s,d,u){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="算电岛技术深度拆解-100-绿电直连的算电岛-是真实用还是秀肌肉" tabindex="-1">算电岛技术深度拆解：100%绿电直连的算电岛，是真实用还是秀肌肉？ <a class="header-anchor" href="#算电岛技术深度拆解-100-绿电直连的算电岛-是真实用还是秀肌肉" aria-label="Permalink to &quot;算电岛技术深度拆解：100%绿电直连的算电岛，是真实用还是秀肌肉？&quot;">​</a></h1><h2 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to &quot;主题&quot;">​</a></h2><p>2026年6月6日，特锐德发布全球首创的&quot;算力中心高压交直流预制舱供电站&quot;——算电岛。本文拆解其核心技术方案，判断落地时间线，评估供应链受益环节。</p><h2 id="核心观点" tabindex="-1">核心观点 <a class="header-anchor" href="#核心观点" aria-label="Permalink to &quot;核心观点&quot;">​</a></h2><ul><li>算电岛不是骗局，是一张&quot;有扎实地基但不完整的蓝图&quot;</li><li>预制舱+碳化硅+HVDC部分 = 真实可交付 ✅</li><li>SST+动态构网+AI优化部分 = 需2-3年兑现 ⏳</li></ul><h2 id="技术拆解" tabindex="-1">技术拆解 <a class="header-anchor" href="#技术拆解" aria-label="Permalink to &quot;技术拆解&quot;">​</a></h2><h3 id="可落地-1-2年内" tabindex="-1">可落地（1-2年内） <a class="header-anchor" href="#可落地-1-2年内" aria-label="Permalink to &quot;可落地（1-2年内）&quot;">​</a></h3><ol><li><strong>碳化硅HVDC变流</strong> ★★★★☆ — 特来电80GW运营规模验证，技术迁移成熟</li><li><strong>800V直挂储能</strong> ★★★★☆ — 拓扑方案成熟，2026H2可交付</li><li><strong>预制舱模块化</strong> ★★★★★ — 特锐德核心能力，5个月交付</li></ol><h3 id="需验证-2-3年" tabindex="-1">需验证（2-3年） <a class="header-anchor" href="#需验证-2-3年" aria-label="Permalink to &quot;需验证（2-3年）&quot;">​</a></h3><ol start="4"><li><strong>动态构网技术</strong> ★★★☆☆ — 概念先进但缺乏实际运行数据</li><li><strong>SST固态变压器</strong> ★★☆☆☆ — 220kV级全球无商用先例，2027挂网示范</li><li><strong>AI潮流全局优化</strong> ★★★☆☆ — 持续迭代，需现场数据验证</li></ol><h2 id="供应链受益" tabindex="-1">供应链受益 <a class="header-anchor" href="#供应链受益" aria-label="Permalink to &quot;供应链受益&quot;">​</a></h2><h3 id="第一梯队" tabindex="-1">第一梯队 <a class="header-anchor" href="#第一梯队" aria-label="Permalink to &quot;第一梯队&quot;">​</a></h3><ul><li>特锐德（300001.SZ）— 直接受益</li><li>碳化硅产业链（中瓷电子/时代电气/三安光电）</li><li>储能系统（宁德时代/阳光电源）</li></ul><h3 id="第二梯队" tabindex="-1">第二梯队 <a class="header-anchor" href="#第二梯队" aria-label="Permalink to &quot;第二梯队&quot;">​</a></h3><ul><li>配电设备（金盘科技/英维克）</li><li>HVDC/SST（四方股份/国电南瑞）</li></ul><h3 id="第三梯队" tabindex="-1">第三梯队 <a class="header-anchor" href="#第三梯队" aria-label="Permalink to &quot;第三梯队&quot;">​</a></h3><ul><li>电力AI调度（国能日新/路明星光）</li></ul><h2 id="数据来源" tabindex="-1">数据来源 <a class="header-anchor" href="#数据来源" aria-label="Permalink to &quot;数据来源&quot;">​</a></h2><ul><li>21世纪经济报道 2026年6月22日</li><li>青岛政务网 2026-06-07</li><li>特锐德官网</li><li>国信证券研报 2026-06-09</li><li>施耐德电气《算电协同洞察报告》2025</li><li>国金证券《算电协同纳入国家战略》2026-04</li></ul>',19)])])}const q=l(r,[["render",o]]);export{c as __pageData,q as default};
